/* Original Carousel Studio · street-theology · 1080 × 1350 */
@font-face{font-family:"Montserrat";font-weight:400;src:url("/fonts/montserrat-400.woff") format("woff");font-display:block}
@font-face{font-family:"Montserrat";font-weight:800;src:url("/fonts/montserrat-800.woff") format("woff");font-display:block}
@font-face{font-family:"Cormorant Garamond";font-weight:400;src:url("/fonts/cormorant-400.woff") format("woff");font-display:block}
@font-face{font-family:"Cormorant Garamond";font-weight:600;src:url("/fonts/cormorant-600.woff") format("woff");font-display:block}
@font-face{font-family:"Cormorant Garamond";font-weight:700;src:url("/fonts/cormorant-700.woff") format("woff");font-display:block}
@font-face{font-family:"Bebas Neue";font-weight:400;src:url("/fonts/bebas-400.woff") format("woff");font-display:block}
.carousel-preview-stage{width:100%;display:grid;place-items:center;min-height:0}.carousel-artboard,.carousel-export-artboard{position:relative;overflow:hidden;aspect-ratio:4/5;background:linear-gradient(180deg,#123044 0%,#0b2231 54%,#07141e 100%);color:#f4f0e9;container-type:inline-size;isolation:isolate}.carousel-artboard{width:min(100%,560px,calc((100vh - 220px)*.8));box-shadow:inset 0 0 0 1px rgba(255,255,255,.06),0 20px 60px rgba(0,0,0,.16)}.carousel-export-artboard{aspect-ratio:auto}.carousel-artwork{position:absolute;inset:0;overflow:hidden;font-family:'Montserrat',Arial,sans-serif}.carousel-ambient{position:absolute;width:62%;height:70%;filter:blur(7cqw);opacity:.44;pointer-events:none}.carousel-ambient-red{left:-34%;bottom:-34%;background:radial-gradient(circle,rgba(153,25,39,.46),transparent 68%)}.carousel-ambient-blue{right:-32%;top:-34%;background:radial-gradient(circle,rgba(38,82,126,.43),transparent 68%)}.carousel-grain{position:absolute;inset:0;opacity:calc(.025 + var(--carousel-grain,.6)*.07);pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.carousel-city{position:absolute;left:-2%;right:-2%;bottom:0;height:16%;opacity:.3;background:#02070a;clip-path:polygon(0 35%,7% 35%,7% 9%,13% 9%,13% 28%,20% 28%,20% 43%,28% 43%,28% 18%,34% 18%,34% 34%,43% 34%,43% 7%,48% 7%,48% 45%,56% 45%,56% 23%,63% 23%,63% 41%,72% 41%,72% 17%,78% 17%,78% 33%,87% 33%,87% 3%,92% 3%,92% 37%,100% 37%,100% 100%,0 100%)}.carousel-brand-mark{position:absolute;z-index:4;right:6.3%;top:5.4%;width:11.5%;height:auto;object-fit:contain}.carousel-pathway-label{position:absolute;z-index:4;left:6.5%;top:6.5%;font:700 1.22cqw/1.2 'Montserrat',sans-serif;letter-spacing:.18em;color:#a9b2b9}.carousel-copy{position:absolute;z-index:5;left:7%;right:7%;top:var(--copy-y,49%);transform:translateY(-50%);display:grid;justify-items:var(--copy-align,center);text-align:var(--copy-align,center);gap:var(--copy-gap,2.3cqw)}.carousel-copy>span{font:800 1.8cqw/1.2 'Montserrat',sans-serif;letter-spacing:.2em;color:#db2a40;text-transform:uppercase}.carousel-copy>strong{display:grid;width:var(--title-width,90%);max-width:100%;font:800 calc(10.7cqw * var(--headline-scale,1))/.9 'Montserrat',Arial,sans-serif;letter-spacing:-.055em;text-transform:uppercase;text-wrap:balance}.carousel-copy>strong>i{display:block;font:inherit;letter-spacing:inherit;text-transform:inherit;font-style:normal}.carousel-copy>strong.fit-md{font-size:calc(9.4cqw * var(--headline-scale,1))}.carousel-copy>strong.fit-lg{font-size:calc(8cqw * var(--headline-scale,1))}.carousel-copy>strong.fit-xl{font-size:calc(6.9cqw * var(--headline-scale,1));line-height:.94}.carousel-copy>strong.fit-xxl{font-size:calc(5.8cqw * var(--headline-scale,1));line-height:.98}.carousel-copy>p{width:var(--body-width,78%);margin:.25cqw 0 0;color:#c7ccd0;font:500 calc(2.55cqw * var(--body-scale,1))/1.38 'Montserrat',sans-serif;text-wrap:balance}.carousel-copy>em{display:inline-block;margin-top:.3cqw;padding:1cqw 1.4cqw .9cqw;background:#c61d34;color:#fff;font:800 1.65cqw/1 'Montserrat',sans-serif;letter-spacing:.1em;font-style:normal}.carousel-crown{width:calc(20cqw * var(--crown-scale,1));height:calc(10.8cqw * var(--crown-scale,1));fill:none;stroke:currentColor;stroke-width:10;stroke-linejoin:round;stroke-linecap:round}.carousel-footer{position:absolute;z-index:5;left:6.5%;right:6.5%;bottom:5.2%;display:flex;align-items:center;justify-content:space-between;color:#9aa2a8;font:700 1.35cqw/1.2 'Montserrat',sans-serif;letter-spacing:.12em}.is-cover .carousel-copy>strong{font-size:calc(12cqw * var(--headline-scale,1));max-width:90%}.is-cover .carousel-copy>p{font-size:calc(2.35cqw * var(--body-scale,1));max-width:72%}.is-cta .carousel-copy>strong{font-size:calc(8.5cqw * var(--headline-scale,1))}
.carousel-artboard.is-editorial,.carousel-export-artboard.is-editorial{background:#f3f0e9;color:#102334}.is-editorial .carousel-ambient{opacity:.04}.is-editorial .carousel-grain{mix-blend-mode:multiply;opacity:.08}.is-editorial .carousel-city{background:#22313a;opacity:.06}.is-editorial .carousel-pathway-label,.is-editorial .carousel-footer{color:#6d7377}.is-editorial .carousel-copy>strong{font-family:'Cormorant Garamond',Georgia,serif;font-weight:600;letter-spacing:-.04em}.is-editorial .carousel-copy>p{font-family:'Cormorant Garamond',Georgia,serif;font-size:calc(3cqw * var(--body-scale,1));color:#4a5258}.is-editorial .carousel-copy>span{color:#a62739}.carousel-artboard.is-cinematic,.carousel-export-artboard.is-cinematic{background:radial-gradient(circle at 50% 34%,#203747 0%,#09131b 56%,#030607 100%)}.is-cinematic .carousel-ambient{opacity:.65}.is-cinematic .carousel-copy>strong{font-family:'Cormorant Garamond',Georgia,serif;font-weight:500;letter-spacing:-.04em}.is-cinematic .carousel-copy>p{font-family:'Cormorant Garamond',Georgia,serif;font-size:calc(3cqw * var(--body-scale,1));color:#b8c0c6}.carousel-artboard.is-manifesto,.carousel-export-artboard.is-manifesto{background:linear-gradient(180deg,#102d3d,#092131 60%,#07161f)}.is-manifesto .carousel-copy>strong{font-family:'Montserrat',sans-serif;font-weight:800;font-size:calc(8cqw * var(--headline-scale,1));line-height:1}.is-manifesto .carousel-copy>p{font-style:italic}.carousel-artboard.is-verse,.carousel-export-artboard.is-verse{background:#f2f1ed;color:#0b2840}.is-verse .carousel-grain{mix-blend-mode:multiply;opacity:.11}.is-verse .carousel-city{display:none}.is-verse .carousel-brand-mark{filter:none}.is-verse .carousel-pathway-label,.is-verse .carousel-footer{color:#556571}
.carousel-verse-connection{position:absolute;z-index:5;left:10%;right:10%;top:50%;transform:translateY(-50%);display:grid;justify-items:center;text-align:center;gap:3cqw}.carousel-verse-connection>span{justify-self:start;font:800 2cqw/1 'Montserrat',sans-serif;color:#c11d31;font-style:italic}.carousel-verse-connection>strong{font:400 10.5cqw/.95 'Bebas Neue','Montserrat',sans-serif;letter-spacing:.01em;color:inherit}.carousel-verse-connection>p{margin:0;max-width:88%;font:600 2.8cqw/1.35 'Montserrat',sans-serif;color:inherit}.carousel-verse-connection>i{font:700 6cqw/1 'Montserrat',sans-serif;color:#c11d31;font-style:normal}
/* Rules-first Carousel Studio layer. Keeps the original studio architecture and overrides only art direction. */
.carousel-studio-page{
  --ag-carousel-paper:#f5f7f4;
  --ag-carousel-white:#fff;
  --ag-carousel-ink:#10202a;
  --ag-carousel-ink-2:#263a44;
  --ag-carousel-muted:#66777d;
  --ag-carousel-line:#d9e1df;
  --ag-carousel-crimson:#a12d3d;
  --ag-carousel-blue:#15566a;
  --ag-carousel-blue-soft:#dcebee;
}

/* Shared readability rules from the visual-design spec. */
.carousel-artboard,.carousel-export-artboard{background:var(--ag-carousel-ink);color:var(--ag-carousel-paper)}
.carousel-copy{left:8%;right:8%;gap:max(1.7cqw,var(--copy-gap,2.3cqw))}
.carousel-copy>span{color:var(--ag-carousel-crimson);font-size:1.55cqw;letter-spacing:.16em}
.carousel-copy>strong{letter-spacing:-.035em;line-height:.94}
.carousel-copy>p{color:var(--ag-carousel-blue-soft);font-size:calc(2.45cqw * var(--body-scale,1));line-height:1.5;max-width:86%}
.carousel-copy>em{background:var(--ag-carousel-crimson);color:var(--ag-carousel-white);padding:1.05cqw 1.55cqw .95cqw}
.carousel-pathway-label{left:6.5%;top:6.2%;color:#b9c6ca}
.carousel-footer{left:6.5%;right:6.5%;bottom:5.2%;color:#aebbc0}
.carousel-brand-mark{right:6.3%;top:5.2%;width:9.8%}
.carousel-grain{opacity:calc(.01 + var(--carousel-grain,.6)*.025)}
.carousel-city{opacity:.18}
.is-cover .carousel-copy>strong{font-size:calc(10.7cqw * var(--headline-scale,1));max-width:88%}
.is-cover .carousel-copy>p{font-size:calc(2.3cqw * var(--body-scale,1));max-width:76%}
.is-cta .carousel-copy>strong{font-size:calc(7.7cqw * var(--headline-scale,1))}

/* Street Theology: bold doctrine, controlled grit, high contrast. */
.carousel-artboard.is-street,.carousel-export-artboard.is-street{background:linear-gradient(180deg,#10202a 0%,#0c1b24 62%,#08131a 100%);color:var(--ag-carousel-paper)}
.is-street .carousel-copy>strong{font-family:'Montserrat',Arial,sans-serif;font-weight:850;color:var(--ag-carousel-paper)}
.is-street .carousel-copy>p{font-family:'Montserrat',Arial,sans-serif;font-weight:500;color:#dcebee}
.is-street .carousel-ambient-red{background:radial-gradient(circle,rgba(161,45,61,.34),transparent 68%)}
.is-street .carousel-ambient-blue{background:radial-gradient(circle,rgba(21,86,106,.32),transparent 68%)}
.is-street .carousel-copy>em{background:var(--ag-carousel-crimson)}

/* Brand White Editorial: teaching/word-study system. Calm, readable, tactile. */
.carousel-artboard.is-editorial,.carousel-export-artboard.is-editorial{background:var(--ag-carousel-paper);color:var(--ag-carousel-ink)}
.is-editorial .carousel-brand-mark{content:url('/brand/apostolic-guide-mark.png')}
.is-editorial .carousel-ambient{opacity:.025}
.is-editorial .carousel-city{display:none}
.is-editorial .carousel-pathway-label{color:var(--ag-carousel-crimson)}
.is-editorial .carousel-footer{color:var(--ag-carousel-muted)}
.is-editorial .carousel-copy{left:9%;right:9%;gap:max(2cqw,var(--copy-gap,2.3cqw))}
.is-editorial .carousel-copy>strong{font-family:'Cormorant Garamond',Georgia,serif;font-weight:650;letter-spacing:-.028em;line-height:.98;color:var(--ag-carousel-ink)}
.is-editorial .carousel-copy>p{font-family:'Montserrat',Arial,sans-serif;font-weight:500;font-size:calc(2.42cqw * var(--body-scale,1));line-height:1.55;color:var(--ag-carousel-ink-2)}
.is-editorial .carousel-copy>span{color:var(--ag-carousel-crimson)}
.is-editorial .carousel-copy>em{background:var(--ag-carousel-crimson);color:#fff}
.is-editorial.is-cover .carousel-copy>strong{font-size:calc(10.1cqw * var(--headline-scale,1))}

/* Cinematic: restrained type over atmosphere, never murky copy. */
.carousel-artboard.is-cinematic,.carousel-export-artboard.is-cinematic{background:radial-gradient(circle at 54% 30%,#263a44 0%,#10202a 48%,#071016 100%);color:var(--ag-carousel-paper)}
.is-cinematic .carousel-ambient{opacity:.42}
.is-cinematic .carousel-city{opacity:.12}
.is-cinematic .carousel-copy>strong{font-family:'Cormorant Garamond',Georgia,serif;font-weight:600;letter-spacing:-.025em;line-height:.98;color:#fff;font-size:calc(8.8cqw * var(--headline-scale,1))}
.is-cinematic .carousel-copy>p{font-family:'Montserrat',Arial,sans-serif;font-weight:500;font-size:calc(2.35cqw * var(--body-scale,1));line-height:1.55;color:#dcebee}
.is-cinematic .carousel-copy>span{color:#f1a5af}
.is-cinematic .carousel-pathway-label,.is-cinematic .carousel-footer{color:#b9c8cd}

/* Verse Connection: teaching diagram. Fixes low-contrast body copy on white. */
.carousel-artboard.is-verse,.carousel-export-artboard.is-verse{background:var(--ag-carousel-paper);color:var(--ag-carousel-ink)}
.is-verse .carousel-brand-mark{content:url('/brand/apostolic-guide-mark.png')}
.is-verse .carousel-city,.is-verse .carousel-ambient{display:none}
.is-verse .carousel-pathway-label{color:var(--ag-carousel-crimson)}
.is-verse .carousel-footer{color:var(--ag-carousel-muted)}
.is-verse .carousel-copy>strong{font-family:'Montserrat',Arial,sans-serif;font-weight:800;color:var(--ag-carousel-ink);letter-spacing:-.035em}
.is-verse .carousel-copy>p{font-family:'Montserrat',Arial,sans-serif;font-weight:500;color:var(--ag-carousel-ink-2);font-size:calc(2.5cqw * var(--body-scale,1));line-height:1.52}
.is-verse .carousel-copy>span{color:var(--ag-carousel-crimson)}
.is-verse .carousel-copy>em{background:var(--ag-carousel-crimson);color:#fff}
.carousel-verse-connection{left:9%;right:9%;gap:2.7cqw}
.carousel-verse-connection>span{justify-self:center;color:var(--ag-carousel-crimson);font-size:1.7cqw;letter-spacing:.12em;font-style:normal}
.carousel-verse-connection>strong{font-size:9.2cqw;color:var(--ag-carousel-ink)}
.carousel-verse-connection>p{max-width:84%;font-size:2.45cqw;line-height:1.5;color:var(--ag-carousel-ink-2)}
.carousel-verse-connection>i{color:var(--ag-carousel-crimson);font-size:5.2cqw}

/* Manifesto: one statement, little supporting copy, no crown. */
.carousel-artboard.is-manifesto,.carousel-export-artboard.is-manifesto{background:linear-gradient(180deg,#10202a 0%,#0d1b24 100%);color:var(--ag-carousel-paper)}
.is-manifesto .carousel-city{display:none}
.is-manifesto .carousel-ambient{opacity:.18}
.is-manifesto .carousel-copy>strong{font-family:'Montserrat',Arial,sans-serif;font-weight:800;font-size:calc(7.4cqw * var(--headline-scale,1));line-height:1.02;letter-spacing:-.025em;color:#fff}
.is-manifesto .carousel-copy>p{font-family:'Cormorant Garamond',Georgia,serif;font-size:calc(2.8cqw * var(--body-scale,1));line-height:1.48;color:#dcebee;font-style:italic}
.is-manifesto .carousel-copy>span{color:#f1a5af}
.carousel-crown{display:none!important}


.carousel-copy>p{white-space:pre-wrap}.carousel-copy>em:empty,.carousel-copy>span:empty{display:none}
